{
  "name": "@juristechllc/fireworks-serialized-provider",
  "version": "0.1.1",
  "description": "Otto-owned provider wrapper for @ai-sdk/openai-compatible that enforces strict tool-use serialization (one tool_call per stream). Addresses the fire-and-forget tool-call bug observed with Kimi K2.5 on Fireworks.ai where the model emits additional tool_use blocks before prior tool_results have been returned. Keyed on Fireworks baseURL; applies uniformly to every model routed through fireworks-ai.",
  "keywords": [
    "ai-sdk",
    "openai-compatible",
    "fireworks",
    "kimi",
    "tool-use",
    "serialization",
    "opencode",
    "otto"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/JurisTechLLC/Otto-OpenWork.git",
    "directory": "OpenWork/starter/apps/fireworks-serialized-provider"
  },
  "bugs": {
    "url": "https://github.com/JurisTechLLC/Otto-OpenWork/issues"
  },
  "homepage": "https://github.com/JurisTechLLC/Otto-OpenWork/tree/master/OpenWork/starter/apps/fireworks-serialized-provider#readme",
  "type": "module",
  "main": "./src/index.mjs",
  "exports": {
    ".": "./src/index.mjs",
    "./serialization-transform": "./src/serialization-transform.mjs"
  },
  "files": [
    "src",
    "README.md"
  ],
  "scripts": {
    "test": "node --test __tests__/*.test.mjs"
  },
  "peerDependencies": {
    "@ai-sdk/openai-compatible": "*"
  },
  "publishConfig": {
    "access": "public"
  }
}

// index.mjs — Otto's serialized Fireworks provider.
//
// This module is loaded by OpenCode's provider loader via the `"npm"` field of
// a provider entry in `opencode.jsonc`. The loader imports the module and
// picks whichever export name starts with `create` (see upstream
// `sst/opencode` packages/opencode/src/provider/provider.ts, around
// `const fn = mod[Object.keys(mod).find((key) => key.startsWith("create"))!]`).
//
// The shape returned by `createFireworksSerialized` satisfies the AI SDK's
// `Provider` interface: `{ languageModel(modelId): LanguageModelV3, ... }`.
//
// All this module does at runtime is:
//
//   1. Dynamically import `@ai-sdk/openai-compatible` (the SAME provider
//      Otto used before P0c) and construct the base SDK with the caller's
//      options (baseURL, apiKey, headers, fetch, etc.).
//   2. Return an SDK proxy whose `languageModel(modelId)` wraps the base
//      model's `doStream` with a TransformStream enforcing tool-use
//      serialization (see ./serialization-transform.mjs).
//
// It does NOT touch authentication, routing, cookies, the chrome-bridge, the
// kill switch, or anything else. The contract with OpenCode, with Fireworks,
// and with every model behind fireworks-ai's baseURL is preserved byte-for-byte
// except for the single invariant: "at most one committed tool-call per stream".
//
// Why the wrapper lives here (NOT in @ai-sdk/openai-compatible or upstream
// OpenCode): keeping OpenCode upstream-updatable is a hard architectural
// constraint for this project. See AGENTS.md "Agent Guidelines for development"
// and repo knowledge "When working on JurisTechLLC/Otto-OpenWork or modifying
// OpenCode/OpenWork functionality".

import { createRequire } from "node:module";
import { createSerializationTransform } from "./serialization-transform.mjs";

// Load `@ai-sdk/openai-compatible` synchronously via `createRequire` so the
// outer shim can forward `specificationVersion` / `supportedUrls` from the
// real inner model rather than hardcoding a version number. The earlier 0.1.0
// hardcoded `"v3"` which made the package unusable against `ai@^5` +
// `@ai-sdk/openai-compatible@^1` (where the inner model reports `"v2"` and
// AI SDK's `resolveLanguageModel` rejects `"v3"` with
// `UnsupportedModelVersionError`). Forwarding sidesteps that class of bug
// entirely — whatever version the installed inner SDK reports, we report.
//
// `@ai-sdk/openai-compatible` ships dual CJS + ESM (`main` = dist/index.js,
// `module` = dist/index.mjs), so `createRequire` can resolve it in any Node
// version ≥ 12.

/**
 * Find the first `create*` export on an imported module — matches
 * OpenCode's provider loader heuristic so the same discovery rule applies in
 * tests as in production.
 *
 * @param {Record<string, unknown>} mod
 * @returns {Function}
 */
function findCreateExport(mod) {
  for (const key of Object.keys(mod)) {
    if (key.startsWith("create") && typeof mod[key] === "function") {
      return /** @type {Function} */ (mod[key]);
    }
  }
  throw new Error(
    "@juristechllc/fireworks-serialized-provider: the underlying `@ai-sdk/openai-compatible` module did not export a `create*` factory.",
  );
}

/**
 * Wrap a `LanguageModelV3` instance so its `doStream` result is piped through
 * the serialization transform. `doGenerate` is delegated untouched — non-stream
 * calls already return a single complete response, so serialization is a no-op
 * for them.
 *
 * @param {object} model
 * @returns {object}
 */
export function wrapLanguageModelWithSerialization(model) {
  if (!model || typeof model !== "object") return model;
  const originalDoStream =
    typeof model.doStream === "function" ? model.doStream.bind(model) : null;
  const originalDoGenerate =
    typeof model.doGenerate === "function" ? model.doGenerate.bind(model) : null;

  return {
    specificationVersion: model.specificationVersion,
    provider: model.provider,
    modelId: model.modelId,
    supportedUrls: model.supportedUrls,

    doGenerate: originalDoGenerate,

    doStream: originalDoStream
      ? async function doStreamSerialized(options) {
          const result = await originalDoStream(options);
          if (!result || !result.stream || typeof result.stream.pipeThrough !== "function") {
            return result;
          }
          const { stream, ...rest } = result;
          return {
            ...rest,
            stream: stream.pipeThrough(createSerializationTransform()),
          };
        }
      : undefined,
  };
}

/**
 * Factory consumed by the OpenCode provider loader.
 *
 * The name MUST start with `create` so OpenCode's `Object.keys(mod).find(k => k.startsWith("create"))`
 * discovery picks it up.
 *
 * @param {Record<string, any>} options
 * @returns {object} An SDK compatible with OpenCode's `Provider` expectation:
 *   `{ languageModel(modelId): LanguageModelV3, ... }`.
 */
export function createFireworksSerialized(options = {}) {
  // Synchronously load `@ai-sdk/openai-compatible`. Using `createRequire`
  // (vs. dynamic `import()`) lets us return a fully-constructed base SDK
  // from inside this sync factory, which in turn lets `languageModel(modelId)`
  // synchronously build a wrapper whose `specificationVersion` /
  // `supportedUrls` are forwarded from the inner model rather than
  // hardcoded. This is the fix for the 0.1.0 bug where a hardcoded `"v3"`
  // triggered `UnsupportedModelVersionError` in `ai@^5` consumers whose
  // inner `@ai-sdk/openai-compatible@^1` model reported `"v2"`.
  const require = createRequire(import.meta.url);
  let mod;
  try {
    mod = require("@ai-sdk/openai-compatible");
  } catch (err) {
    throw new Error(
      `@juristechllc/fireworks-serialized-provider: failed to require its peer dependency '@ai-sdk/openai-compatible'. Install it in the consumer workspace. Underlying error: ${err?.message ?? err}`,
    );
  }
  const factory = findCreateExport(mod);
  const base = factory(options);
  if (!base || typeof base.languageModel !== "function") {
    throw new Error(
      "@juristechllc/fireworks-serialized-provider: base SDK does not expose languageModel(modelId).",
    );
  }

  return {
    /**
     * @param {string} modelId
     * @returns {object} LanguageModel-shaped object with serialized doStream.
     *   Spec version / supportedUrls are forwarded from the inner base model
     *   so the shim stays binary-compatible with whatever version of
     *   `@ai-sdk/openai-compatible` is installed (v1 reports `"v2"`,
     *   v2 reports `"v3"`; both work without this package being rebumped).
     */
    languageModel(modelId) {
      return wrapLanguageModelWithSerialization(base.languageModel(modelId));
    },
  };
}

export default createFireworksSerialized;
